import base64
import json
import os
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import Any, Dict, List, Optional

import boto3


STANDARD_SCHEMA_VERSION = "1.0"


def normalize_expense_document(
    file_bytes: bytes,
    *,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    client = boto3.client("textract", region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1")
    response = client.analyze_expense(Document={"Bytes": file_bytes})
    return _normalize_textract_analyze_expense(response)


def normalize_expense_document_from_path(
    file_path: str,
    *,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    with open(file_path, "rb") as f:
        return normalize_expense_document(f.read(), region_name=region_name)


def normalize_expense_document_from_s3(
    bucket: str,
    key: str,
    *,
    region_name: Optional[str] = None,
    version_id: Optional[str] = None,
) -> Dict[str, Any]:
    client = boto3.client("textract", region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1")
    document_location: Dict[str, Any] = {"S3Object": {"Bucket": bucket, "Name": key}}
    if version_id:
        document_location["S3Object"]["Version"] = version_id
    response = client.analyze_expense(Document=document_location)
    normalized = _normalize_textract_analyze_expense(response)
    normalized["source"] = {
        "provider": "aws_textract",
        "operation": "AnalyzeExpense",
        "s3_bucket": bucket,
        "s3_key": key,
        "s3_version_id": version_id,
    }
    return normalized


def _normalize_textract_analyze_expense(response: Dict[str, Any]) -> Dict[str, Any]:
    documents = response.get("ExpenseDocuments", []) or []
    normalized_documents = [_normalize_expense_document(doc) for doc in documents]

    return {
        "schema_version": STANDARD_SCHEMA_VERSION,
        "provider": "aws_textract",
        "operation": "AnalyzeExpense",
        "document_count": len(normalized_documents),
        "documents": normalized_documents,
        "raw_response_metadata": {
            "document_metadata": response.get("DocumentMetadata"),
        },
    }


def _normalize_expense_document(expense_document: Dict[str, Any]) -> Dict[str, Any]:
    summary_fields = expense_document.get("SummaryFields", []) or []
    line_item_groups = expense_document.get("LineItemGroups", []) or []

    mapped_fields = _map_summary_fields(summary_fields)

    vendor_name = _pick_first_nonempty(
        mapped_fields,
        [
            "VENDOR_NAME",
            "SUPPLIER_NAME",
            "RECEIVER_NAME",
        ],
    )
    vendor_address = _pick_first_nonempty(
        mapped_fields,
        [
            "VENDOR_ADDRESS",
            "SUPPLIER_ADDRESS",
            "RECEIVER_ADDRESS",
        ],
    )
    vendor_phone = _pick_first_nonempty(
        mapped_fields,
        [
            "VENDOR_PHONE",
            "SUPPLIER_PHONE",
            "RECEIVER_PHONE",
        ],
    )
    vendor_url = _pick_first_nonempty(mapped_fields, ["VENDOR_URL"])
    vendor_tax_id = _pick_first_nonempty(
        mapped_fields,
        [
            "VENDOR_VAT_NUMBER",
            "SUPPLIER_VAT_NUMBER",
            "TAX_PAYER_ID",
        ],
    )

    invoice_id = _pick_first_nonempty(
        mapped_fields,
        [
            "INVOICE_RECEIPT_ID",
            "INVOICE_RECEIPT_NUMBER",
            "ORDER_ID",
            "RECEIPT_NUMBER",
        ],
    )
    purchase_order = _pick_first_nonempty(mapped_fields, ["PO_NUMBER", "ORDER_ID"])
    invoice_date = _pick_first_nonempty(
        mapped_fields,
        [
            "INVOICE_RECEIPT_DATE",
            "TRANSACTION_DATE",
        ],
    )
    due_date = _pick_first_nonempty(mapped_fields, ["DUE_DATE"])
    payment_terms = _pick_first_nonempty(mapped_fields, ["PAYMENT_TERMS"])

    currency = _pick_currency(mapped_fields)
    subtotal = _pick_amount(mapped_fields, ["SUBTOTAL"])
    tax = _pick_amount(mapped_fields, ["TAX", "VAT", "TOTAL_TAX"])
    discount = _pick_amount(mapped_fields, ["DISCOUNT"])
    shipping = _pick_amount(mapped_fields, ["SHIPPING_HANDLING_CHARGE", "FREIGHT"])
    tip = _pick_amount(mapped_fields, ["TIP"])
    total = _pick_amount(mapped_fields, ["TOTAL", "AMOUNT_DUE", "BALANCE"])
    amount_paid = _pick_amount(mapped_fields, ["AMOUNT_PAID"])
    previous_unpaid_balance = _pick_amount(mapped_fields, ["PREVIOUS_UNPAID_BALANCE"])

    bill_to = {
        "name": _pick_first_nonempty(mapped_fields, ["BILL_TO", "CUSTOMER_NAME"]),
        "address": _pick_first_nonempty(mapped_fields, ["BILL_TO_ADDRESS", "CUSTOMER_ADDRESS"]),
    }
    ship_to = {
        "name": _pick_first_nonempty(mapped_fields, ["SHIP_TO_NAME"]),
        "address": _pick_first_nonempty(mapped_fields, ["SHIP_TO_ADDRESS"]),
    }

    line_items = _normalize_line_items(line_item_groups)

    return {
        "expense_index": expense_document.get("ExpenseIndex"),
        "document_type": _normalize_document_type(expense_document.get("ExpenseType")),
        "invoice": {
            "invoice_id": invoice_id,
            "purchase_order": purchase_order,
            "invoice_date": invoice_date,
            "due_date": due_date,
            "payment_terms": payment_terms,
        },
        "vendor": {
            "name": vendor_name,
            "address": vendor_address,
            "phone": vendor_phone,
            "url": vendor_url,
            "tax_id": vendor_tax_id,
        },
        "customer": {
            "bill_to": _none_if_empty_dict(bill_to),
            "ship_to": _none_if_empty_dict(ship_to),
        },
        "amounts": {
            "currency": currency,
            "subtotal": subtotal,
            "tax": tax,
            "discount": discount,
            "shipping": shipping,
            "tip": tip,
            "total": total,
            "amount_paid": amount_paid,
            "previous_unpaid_balance": previous_unpaid_balance,
        },
        "line_items": line_items,
        "fields": _flatten_fields(mapped_fields),
        "confidence": _document_confidence(summary_fields, line_item_groups),
    }


def _normalize_document_type(expense_type: Optional[str]) -> Optional[str]:
    if not expense_type:
        return None
    value = expense_type.strip().lower()
    if "invoice" in value:
        return "invoice"
    if "receipt" in value:
        return "receipt"
    return expense_type


def _map_summary_fields(summary_fields: List[Dict[str, Any]]) -> Dict[str, List[Dict[str, Any]]]:
    mapped: Dict[str, List[Dict[str, Any]]] = {}
    for field in summary_fields:
        key = ((field.get("Type") or {}).get("Text") or "UNKNOWN").strip().upper()
        mapped.setdefault(key, []).append(_normalize_summary_field(field))
    return mapped


def _normalize_summary_field(field: Dict[str, Any]) -> Dict[str, Any]:
    value_detection = field.get("ValueDetection") or {}
    label_detection = field.get("LabelDetection") or {}
    currency = field.get("Currency") or {}
    group_properties = field.get("GroupProperties") or []

    return {
        "type": ((field.get("Type") or {}).get("Text")),
        "value": value_detection.get("Text"),
        "value_raw": value_detection,
        "label": label_detection.get("Text"),
        "confidence": _coalesce_number(value_detection.get("Confidence"), field.get("Confidence")),
        "currency_code": currency.get("Code"),
        "currency_confidence": currency.get("Confidence"),
        "page_number": _extract_page_number([value_detection, label_detection]),
        "groups": [
            {
                "id": gp.get("Id"),
                "types": gp.get("Types") or [],
            }
            for gp in group_properties
        ],
    }


def _normalize_line_items(line_item_groups: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []

    for group in line_item_groups:
        for line in group.get("LineItems", []) or []:
            fields_by_type: Dict[str, List[Dict[str, Any]]] = {}
            for field in line.get("LineItemExpenseFields", []) or []:
                key = ((field.get("Type") or {}).get("Text") or "UNKNOWN").strip().upper()
                fields_by_type.setdefault(key, []).append(_normalize_summary_field(field))

            description = _pick_first_nonempty(fields_by_type, ["ITEM", "DESCRIPTION", "PRODUCT_CODE"])
            quantity = _pick_number(fields_by_type, ["QUANTITY"])
            unit_price = _pick_amount(fields_by_type, ["PRICE", "UNIT_PRICE"])
            line_total = _pick_amount(fields_by_type, ["LINE_ITEM_TOTAL", "AMOUNT", "TOTAL"])
            product_code = _pick_first_nonempty(fields_by_type, ["PRODUCT_CODE"])
            unit_of_measure = _pick_first_nonempty(fields_by_type, ["UNIT"])
            item_currency = _pick_currency(fields_by_type)

            items.append(
                {
                    "description": description,
                    "product_code": product_code,
                    "quantity": quantity,
                    "unit_of_measure": unit_of_measure,
                    "unit_price": unit_price,
                    "line_total": line_total,
                    "currency": item_currency,
                    "confidence": _fields_confidence(fields_by_type),
                    "raw_fields": _flatten_fields(fields_by_type),
                }
            )

    return items


def _flatten_fields(fields_by_type: Dict[str, List[Dict[str, Any]]]) -> List[Dict[str, Any]]:
    flattened: List[Dict[str, Any]] = []
    for field_type, values in fields_by_type.items():
        for entry in values:
            flattened.append(
                {
                    "type": field_type,
                    "label": entry.get("label"),
                    "value": entry.get("value"),
                    "confidence": entry.get("confidence"),
                    "currency_code": entry.get("currency_code"),
                    "page_number": entry.get("page_number"),
                    "groups": entry.get("groups"),
                }
            )
    return flattened


def _pick_first_nonempty(fields_by_type: Dict[str, List[Dict[str, Any]]], keys: List[str]) -> Optional[str]:
    for key in keys:
        for entry in fields_by_type.get(key, []):
            value = _clean_text(entry.get("value"))
            if value:
                return value
    return None


def _pick_currency(fields_by_type: Dict[str, List[Dict[str, Any]]]) -> Optional[str]:
    for entries in fields_by_type.values():
        for entry in entries:
            code = _clean_text(entry.get("currency_code"))
            if code:
                return code
    return None


def _pick_amount(fields_by_type: Dict[str, List[Dict[str, Any]]], keys: List[str]) -> Optional[float]:
    for key in keys:
        for entry in fields_by_type.get(key, []):
            amount = _parse_amount(entry.get("value"))
            if amount is not None:
                return amount
    return None


def _pick_number(fields_by_type: Dict[str, List[Dict[str, Any]]], keys: List[str]) -> Optional[float]:
    for key in keys:
        for entry in fields_by_type.get(key, []):
            number = _parse_number(entry.get("value"))
            if number is not None:
                return number
    return None


def _parse_amount(value: Any) -> Optional[float]:
    if value is None:
        return None
    text = str(value).strip()
    if not text:
        return None

    normalized = text.replace(",", "")
    normalized = normalized.replace("$", "").replace("€", "").replace("£", "").replace("¥", "")
    normalized = normalized.replace("USD", "").replace("EUR", "").replace("GBP", "").replace("JPY", "")
    normalized = normalized.strip()

    if normalized.startswith("(") and normalized.endswith(")"):
        normalized = "-" + normalized[1:-1].strip()

    try:
        dec = Decimal(normalized)
        return float(dec.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
    except (InvalidOperation, ValueError):
        return None


def _parse_number(value: Any) -> Optional[float]:
    if value is None:
        return None
    text = str(value).strip().replace(",", "")
    if not text:
        return None
    try:
        return float(Decimal(text))
    except (InvalidOperation, ValueError):
        return None


def _clean_text(value: Any) -> Optional[str]:
    if value is None:
        return None
    text = str(value).strip()
    return text or None


def _extract_page_number(detections: List[Dict[str, Any]]) -> Optional[int]:
    for det in detections:
        geometry = det.get("Geometry") or {}
        page = geometry.get("PageNumber")
        if isinstance(page, int):
            return page
    return None


def _coalesce_number(*values: Any) -> Optional[float]:
    for value in values:
        if value is None:
            continue
        try:
            return float(value)
        except (TypeError, ValueError):
            continue
    return None


def _fields_confidence(fields_by_type: Dict[str, List[Dict[str, Any]]]) -> Optional[float]:
    confidences: List[float] = []
    for entries in fields_by_type.values():
        for entry in entries:
            conf = entry.get("confidence")
            if isinstance(conf, (int, float)):
                confidences.append(float(conf))
    if not confidences:
        return None
    return round(sum(confidences) / len(confidences), 4)


def _document_confidence(summary_fields: List[Dict[str, Any]], line_item_groups: List[Dict[str, Any]]) -> Optional[float]:
    confidences: List[float] = []

    for field in summary_fields:
        conf = ((field.get("ValueDetection") or {}).get("Confidence"))
        if isinstance(conf, (int, float)):
            confidences.append(float(conf))

    for group in line_item_groups:
        for line in group.get("LineItems", []) or []:
            for field in line.get("LineItemExpenseFields", []) or []:
                conf = ((field.get("ValueDetection") or {}).get("Confidence"))
                if isinstance(conf, (int, float)):
                    confidences.append(float(conf))

    if not confidences:
        return None
    return round(sum(confidences) / len(confidences), 4)


def _none_if_empty_dict(value: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    return value if any(v is not None for v in value.values()) else None


def normalized_expense_to_json(data: Dict[str, Any], *, indent: int = 2) -> str:
    return json.dumps(data, indent=indent, ensure_ascii=False)


def normalized_expense_to_base64_json(data: Dict[str, Any]) -> str:
    payload = normalized_expense_to_json(data, indent=0).encode("utf-8")
    return base64.b64encode(payload).decode("ascii")
